package com.aviatortracker.app;

import android.app.*; import android.content.*; import android.graphics.*; import android.media.*; import android.media.projection.*; import android.hardware.display.DisplayManager; import android.os.*; import android.provider.Settings; import android.view.*; import android.widget.*; import androidx.annotation.NonNull; import com.google.mlkit.vision.common.InputImage; import com.google.mlkit.vision.text.*; import com.google.mlkit.vision.text.latin.TextRecognizerOptions; import java.util.*;

public class CaptureService extends Service implements RoundStateMachine.Listener {
    public static final String START="START", STOP="STOP"; private MediaProjection projection; private VirtualDisplay display; private ImageReader reader; private HandlerThread thread; private Handler handler; private TextRecognizer recognizer; private RoundStateMachine machine; private ResultDb db; private WindowManager wm; private View bubble; private long lastFrame;
    @Override public void onCreate(){super.onCreate(); db=new ResultDb(this); machine=new RoundStateMachine(this); recognizer=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS); createChannel();}
    @Override public int onStartCommand(Intent i,int flags,int id){if(i!=null && START.equals(i.getAction())) startCapture(i); return START_STICKY;}
    void startCapture(Intent i){try{startForeground(7,notification("DÃ©marrage de la capture")); MediaProjectionManager m=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE); projection=m.getMediaProjection(i.getIntExtra("resultCode",Activity.RESULT_CANCELED),i.getParcelableExtra("data")); DisplayMetrics dm=getResources().getDisplayMetrics(); int w=dm.widthPixels,h=dm.heightPixels; reader=ImageReader.newInstance(w,h,PixelFormat.RGBA_8888,2); thread=new HandlerThread("aviator-capture");thread.start();handler=new Handler(thread.getLooper()); reader.setOnImageAvailableListener(this::onFrame,handler); display=projection.createVirtualDisplay("AviatorTracker",w,h,dm.densityDpi,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,reader.getSurface(),null,handler); addBubble(); handler.postDelayed(()->notificationUpdate("Capture active â€” OCR toutes les 500 ms"),300); }catch(Exception e){notificationUpdate("Erreur capture: "+e.getMessage());}}
    void onFrame(ImageReader r){long now=SystemClock.elapsedRealtime(); Image image=null; try{image=r.acquireLatestImage(); if(image==null || now-lastFrame<450)return; lastFrame=now; Bitmap full=toBitmap(image); SharedPreferences p=getSharedPreferences("capture",0); int l=p.getInt("left",0),t=p.getInt("top",0),cw=p.getInt("width",0),ch=p.getInt("height",0); if(cw<8||ch<8){diagnostic("WAITING","zone non dÃ©finie","");full.recycle();return;} l=Math.max(0,Math.min(l,full.getWidth()-1));t=Math.max(0,Math.min(t,full.getHeight()-1));cw=Math.min(cw,full.getWidth()-l);ch=Math.min(ch,full.getHeight()-t); Bitmap crop=Bitmap.createBitmap(full,l,t,cw,ch); full.recycle(); recognizer.process(InputImage.fromBitmap(crop,0)).addOnSuccessListener(result->{machine.accept(result.getText());crop.recycle();}).addOnFailureListener(e->{machine.accept("");crop.recycle();}); }catch(Exception e){diagnostic("ERROR",e.getClass().getSimpleName(),"");}finally{if(image!=null)image.close();}}
    Bitmap toBitmap(Image image){Image.Plane pl=image.getPlanes()[0]; ByteBufferHolder h=new ByteBufferHolder(pl.getBuffer()); int stride=pl.getRowStride(),pix=pl.getPixelStride(),pad=stride-pix*image.getWidth(); Bitmap b=Bitmap.createBitmap(image.getWidth()+pad/pix,image.getHeight(),Bitmap.Config.ARGB_8888); b.copyPixelsFromBuffer(h.buffer); Bitmap out=Bitmap.createBitmap(b,0,0,image.getWidth(),image.getHeight());b.recycle();return out;}
    static class ByteBufferHolder { java.nio.ByteBuffer buffer; ByteBufferHolder(java.nio.ByteBuffer b){buffer=b;}}
    void addBubble(){if(!Settings.canDrawOverlays(this))return; wm=(WindowManager)getSystemService(WINDOW_SERVICE); TextView v=new TextView(this);v.setText("âœˆ");v.setTextSize(24);v.setTextColor(Color.WHITE);v.setGravity(Gravity.CENTER);v.setBackgroundColor(0xff512da8);v.setOnClickListener(x->{Intent s=new Intent(this,RegionSelectorActivity.class);s.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(s);});int type=Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE;WindowManager.LayoutParams lp=new WindowManager.LayoutParams(64,64,type,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.END;lp.x=20;lp.y=180;wm.addView(v,lp);bubble=v;}
    @Override public void diagnostic(String state,String ocr,String last){notificationUpdate(state+" | OCR: "+ocr+" | dernier: "+last);}
    @Override public void result(String value){db.add(value);notificationUpdate("RÃ©sultat enregistrÃ©: "+value);}
    Notification notification(String text){return new Notification.Builder(this,"aviator").setContentTitle("Aviator Tracker").setContentText(text).setSmallIcon(android.R.drawable.ic_menu_info_details).setOngoing(true).build();}
    void notificationUpdate(String text){((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(7,notification(text));}
    void createChannel(){if(Build.VERSION.SDK_INT>=26)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel("aviator","Aviator Tracker",NotificationManager.IMPORTANCE_LOW));}
    @Override public IBinder onBind(Intent i){return null;}
    @Override public void onDestroy(){if(bubble!=null&&wm!=null)wm.removeView(bubble);if(display!=null)display.release();if(reader!=null)reader.close();if(projection!=null)projection.stop();if(thread!=null)thread.quitSafely();recognizer.close();super.onDestroy();}
}
